'''GSPO 长度归一化序列级重要性比率：方差对比实验（可直接运行）。

对应单选题的正确选项：降低逐 token 比率引入的高方差问题，改善训练稳定性。
本脚本用随机模拟证实两件事：
1. 逐 token 连乘比率 prod_t r_t 的抖动不随序列长度 L 收敛：对数比率之和的
   标准差按 sqrt(L) 增长，比率本身因此指数级抖动；
2. GSPO 的长度归一化序列级比率 s = exp(mean_t log r_t) 的标准差与 L 无关，
   实测约为单 token 波动除以 sqrt(L)。
运行：python gspo_ratio_variance.py
'''
import math
import random
import statistics

LOG_CLIP = 10.0


def token_log_ratios(rng, length, drift=0.0, noise=0.05):
    '''模拟一条序列上每个 token 的对数比率 log(pi_new/pi_old)。'''
    if length <= 0:
        raise ValueError('length 必须为正整数')
    vals = [rng.gauss(drift, noise) for _ in range(length)]
    return [max(-LOG_CLIP, min(LOG_CLIP, v)) for v in vals]


def token_level_ratio(log_ratios):
    '''逐 token 连乘：prod_t r_t = exp(sum_t log r_t)，长度越长越抖。'''
    if not log_ratios:
        raise ValueError('序列不能为空')
    return math.exp(sum(log_ratios))


def gspo_sequence_ratio(log_ratios):
    '''GSPO：s_i = (prod_t r_t) ** (1/L) = exp(mean_t log r_t)，几何平均即长度归一化。'''
    if not log_ratios:
        raise ValueError('序列不能为空')
    return math.exp(sum(log_ratios) / len(log_ratios))


def clipped(ratio, eps=3e-4):
    '''序列级对称裁剪：|s_i - 1| 超过 eps 的部分被截断，不再产生梯度。'''
    if not 0.0 < eps < 1.0:
        raise ValueError('eps 必须落在 (0, 1)')
    return min(1.0 + eps, max(1.0 - eps, ratio))


def variance_table(lengths, trials, seed=0):
    '''对每个长度重复 trials 次，返回 (长度, 连乘比率 std, GSPO 比率 std)。'''
    rng = random.Random(seed)
    rows = []
    for length in lengths:
        tok, gsp = [], []
        for _ in range(trials):
            lr = token_log_ratios(rng, length)
            tok.append(token_level_ratio(lr))
            gsp.append(gspo_sequence_ratio(lr))
        st, sg = statistics.pstdev(tok), statistics.pstdev(gsp)
        assert sg < st, '长度归一化应当降低比率抖动'
        rows.append((length, st, sg))
    return rows


def main():
    print('长度 逐token连乘std GSPO序列级std 缩减倍数')
    for length, st, sg in variance_table((16, 64, 256), trials=4000):
        print('%4d %14.4f %13.4f %10.1f' % (length, st, sg, st / sg))
    lr = token_log_ratios(random.Random(1), 1)
    assert math.isclose(gspo_sequence_ratio(lr), token_level_ratio(lr))
    print('L=1 时两者相等：', round(gspo_sequence_ratio(lr), 6))
    print('极端比率被裁剪到 1 加减 eps：', clipped(1.0 + 1e-3, 3e-4))
    try:
        gspo_sequence_ratio([])
    except ValueError as err:
        print('空序列报错：', err)


if __name__ == '__main__':
    main()
